import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 amount, bool successExpected) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(c));
        amount = bound(amount, 1, 1 ether);

        // Deploy a helper that always accepts ETH; the fuzzer will try with any non-owner.
        Receiver receiver = new Receiver();
        address receiverAddr = address(receiver);

        // Fund the non-owner attacker.
        vm.deal(nonOwner, amount);

        // Owner's send must always succeed (successExpected = true from setUp context).
        // We check the behavior for the non-owner: it MUST revert because they are not the owner.
        vm.prank(nonOwner);
        bool ok;
        try c.sendTo(receiverAddr, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct invariant: a non-owner call always reverts (ok == false).
        // The mutant removes the owner check, so it succeeds (ok == true) for some input,
        // breaking the invariant that non-owner calls always revert.
        assertTrue(!ok, "non-owner transfer should revert");
    }
}

