import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // Restrict amount to the relevant domain: amounts that do NOT meet the bug's threshold.
        vm.assume(amount > 0);
        vm.assume(amount < 1 ether);
        // Ensure receiver is a valid, payable address that won't revert on transfer.
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));

        // Fund the contract so it can send Ether.
        vm.deal(address(c), 100 ether);
        uint256 balanceBefore = address(c).balance;

        // The owner (deployer by default in setUp) calls sendTo.
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        uint256 balanceAfter = address(c).balance;

        // The reference C (amount > 0) must transfer the funds, so its balance decreases.
        // The buggy M (amount >= 1 ether) reverts for these amounts, so its balance stays the same.
        // This yields a universal property on C for this domain that M violates.
        assertTrue(balanceAfter < balanceBefore);
    }
}

