        vm.deal(address(c), amount);
        balBefore = address(c).balance;

        // Owner calls sendTo(receiver = address(this), amount)
        c.sendTo(address(this), amount);

        // In reference C, contract sends amount to receiver, so balance decreases by amount.
        // In mutant, contract sends amount back to owner (msg.sender), but owner is also receiver,
        // so funds go to owner. Since owner originally funded the contract with vm.deal,
        // contract balance still decreases by amount. But the general rule is:
        // For ANY receiver != address(0), amount > 0, when owner calls sendTo,
        // the contract's balance MUST decrease by amount. The mutant breaks this when
        // receiver is a third party (not owner). Let owner call with an arbitrary receiver.
        // We need an adversarial receiver that does not revert on receive, but we can use
        // a fresh EOA (fuzzed address) since transfer to EOA succeeds.
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(amount > 0);
        vm.assume(receiver != address(0));
        // Ensure receiver is not the owner (address(this) is owner)
        vm.assume(receiver != address(this));

        // Fund contract so it can send
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;

        // owner calls sendTo(receiver, amount)
        c.sendTo(receiver, amount);

        uint256 balAfter = address(c).balance;

        // Rule: Contract's balance must decrease by exactly amount.
        // Reference: funds sent to receiver, contract loses amount.
        // Mutant: funds sent back to owner, contract still loses amount because owner is not contract.
        // Wait, owner is address(this), not the contract. So contract balance decreases in both cases.
        // This property does not distinguish.
        // We need a property that observes the receiver's balance.
        // Since the fuzzer cannot observe receiver's balance (it's an arbitrary EOA),
        // we must deploy a helper that records received ETH and make receiver that helper.
    }
}

contract BalanceProbe {
    uint256 public received;
    receive() external payable {
        received += msg.value;
    }
}

