pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. Keep amount in admissible domain
        vm.assume(amount > 0);
        address owner = address(this);
        Reverter reverter = new Reverter();
        uint256 contractBalanceBefore = address(c).balance;
        // 2. Fund the owner and call sendTo with the reverter as receiver, expecting a revert
        vm.deal(owner, amount);
        vm.prank(owner);
        bool ok = false;
        try c.sendTo{value: amount}(address(reverter), amount) { ok = true; } catch { ok = false; }
        // 3. Assert: if the external call reverted (as expected), the contract's ETH balance must be unchanged (refunded).
        // The buggy version sends to msg.sender instead, which succeeds and reduces the contract's balance.
        assertTrue(!ok ? address(c).balance == contractBalanceBefore : true);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
